<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Text Length Analyzer','description'=>'Analyze characters, words and lines in any text.','url'=>'https://smarttoolz.in/tools/text-length-analyzer/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Text Length Analyzer</h1><p>Get detailed text length statistics.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder="Type or paste text..."></textarea><p id="o"></p></div></section></main><script>i.oninput=()=>{let s=i.value,w=s.trim()?s.trim().split(/\s+/).length:0,l=s?s.split(/\n/).length:0;o.textContent=`Characters: ${s.length} · No spaces: ${s.replace(/\s/g,'').length} · Words: ${w} · Lines: ${l}`}</script><?php smarttoolz_tool_page_end(); ?>